// Atelier (Foyer): precompiles the validators of Scratch projects.
//
// scratch-parser checks a project against JSON schemas with ajv, which builds
// the checking functions at run time with `new Function`. The page of the
// Atelier is served without 'unsafe-eval': that code would be refused, and no
// project could load. The same functions are generated here, once, at build
// time, as plain source files that the bundle includes instead.
//
//   node valideurs.cjs <scratch-editor checkout>
//
// Writes packages/scratch-gui/src/foyer/generated/validate.js and its modules.
// Needs ajv-pack next to the ajv of scratch-parser (see construire.sh).
const fs = require('fs');
const path = require('path');

const root = path.resolve(process.argv[2] || '.');
const parser = path.join(root, 'node_modules', 'scratch-parser');
const out = path.join(root, 'packages', 'scratch-gui', 'src', 'foyer', 'generated');
const Ajv = require(path.join(parser, 'node_modules', 'ajv'));
const pack = require(path.join(root, 'node_modules', 'ajv-pack'));
const schema = name => require(path.join(parser, 'lib', `${name}.json`));

fs.mkdirSync(out, {recursive: true});
const ajv = new Ajv({sourceCode: true});
ajv.addSchema(schema('sb2_definitions')).addSchema(schema('sb3_definitions'));

for (const name of ['sb2_schema', 'sb3_schema', 'sprite2_schema', 'sprite3_schema']) {
    const code = pack(ajv, ajv.compile(schema(name)))
        .replace(/require\('ajv\/lib\/compile\/(\w+)'\)/g, "require('./ajv-$1.js')")
        // The schemas are named by an address on the Scratch site. It is only a name,
        // never fetched, but the Atelier carries no such address: it becomes a URN.
        .replace(/https:\/\/scratch\.mit\.edu\/(\w+\.json)/g, 'urn:atelier:$1')
        .replace(/http:\/\/json-schema\.org\/[\w#/-]*/g, 'urn:json-schema');
    if (/new Function|\beval\(/.test(code)) throw new Error(`${name}: the generated validator still builds code at run time`);
    fs.writeFileSync(path.join(out, `${name}.validate.js`), code);
}
// The two helpers the generated code calls, taken from the same ajv
for (const helper of ['ucs2length', 'equal']) {
    fs.copyFileSync(path.join(parser, 'node_modules', 'ajv', 'lib', 'compile', `${helper}.js`), path.join(out, `ajv-${helper}.js`));
}

// Same behaviour as scratch-parser/lib/validate.js, with the precompiled functions
fs.writeFileSync(path.join(out, 'validate.js'), `// GENERATED by frontend/vendor/atelier/grands/outils/valideurs.cjs (Foyer). Do not edit.
// Replaces scratch-parser/lib/validate.js: same checks, compiled at build time.
var validators = {
    sb2: require('./sb2_schema.validate.js'),
    sb3: require('./sb3_schema.validate.js'),
    sprite2: require('./sprite2_schema.validate.js'),
    sprite3: require('./sprite3_schema.validate.js')
};

module.exports = function (isSprite, input, callback) {
    var validateSb2 = isSprite ? validators.sprite2 : validators.sb2;
    var validateSb3 = isSprite ? validators.sprite3 : validators.sb3;

    if (validateSb2(input)) {
        input.projectVersion = 2;
        return callback(null, input);
    }
    var sb2Errors = validateSb2.errors;

    if (validateSb3(input)) {
        input.projectVersion = 3;
        return callback(null, input);
    }

    callback({
        validationError: 'Could not parse as a valid SB2 or SB3 project.',
        sb2Errors: sb2Errors,
        sb3Errors: validateSb3.errors
    });
};
`);
console.log('[atelier] validators precompiled');
